const appTabs=[...document.querySelectorAll('.bottom-nav [data-view]')];appTabs.forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===id));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===id));window.scrollTo({top:0,behavior:'smooth'})}));let installPrompt=null;const installButton=document.getElementById('installApp');window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;installButton.hidden=false});installButton.addEventListener('click',async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null}else{document.getElementById('toast').textContent='On iPhone: Share → Add to Home Screen. On Android: browser menu → Install app.';showToast()}});window.addEventListener('appinstalled',()=>{installButton.innerHTML='Installed <span>✓</span>'});
